```cpp
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct {
  int product_code;
  char* product_name;
  int stock_count;
} Product;
// Khởi tạo danh sách bằng calloc với hy vọng mọi thứ được reset an toàn
Product* create_product_list(int size) {
  return (Product*)calloc(size, sizeof(Product));
}
// Cập nhật thông tin và nối thêm chuỗi vào tên sản phẩm
void update_product(Product* p, int code, const char* name, int added_stock) {
  p->product_code = code;
  p->stock_count += added_stock;
  // Tính độ dài mới. Trình biên dịch sẽ tính: chiều dài cũ + chiều dài mới + 1
  int new_len = strlen(p->product_name) + strlen(name) + 1;
  // Nới rộng vùng nhớ để chứa tên mới
  p->product_name = (char*)realloc(p->product_name, new_len);
  // Nối chuỗi
  strcat(p->product_name, name);
}
int main() {
  int n = 2;
  Product* inventory = create_product_list(n);
  // Nạp dữ liệu
  update_product(&inventory[0], 101, "Laptop Dell", 50);
  update_product(&inventory[1], 102, "Chuot Logitech", 200);
  printf("\n--- KHO HANG ---\n");
  for (int i = 0; i < n; i++) {
    printf("Ma: %d, Ten: %s, Ton kho: %d\n", inventory[i].product_code,
           inventory[i].product_name, inventory[i].stock_count);
  }
  // Dọn dẹp
  free(inventory);
  return 0;
}
```

